package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

const (
	maxChunkSize = 1 << 20 // 1MB per chunk
	maxTotalSize = 1 << 30 // 1GB total
	uploadDir    = "/var/uploads"
)

// hmacSecret is loaded from the environment at startup rather than hardcoded.
var hmacSecret []byte

// ChunkedUpload tracks multi-part upload state
type ChunkedUpload struct {
	mu          sync.Mutex
	filename    string
	chunks      [][]byte
	totalSize   int64 // tracks accumulated size
	numChunks   int64
	expectedLen int64 // declared total length from client
	finalized   bool
}

var (
	uploads   = make(map[string]*ChunkedUpload)
	uploadsMu sync.RWMutex
)

// sanitizeFilename removes path traversal attempts
func sanitizeFilename(name string) (string, error) {
	// Strip any directory components
	name = filepath.Base(name)
	// Reject names with dots at start (hidden files)
	if strings.HasPrefix(name, ".") {
		return "", fmt.Errorf("invalid filename: hidden files not allowed")
	}
	// Reject empty or current/parent dir references
	if name == "" || name == "." || name == ".." {
		return "", fmt.Errorf("invalid filename")
	}
	// Only allow alphanumeric, dash, underscore, single dot for extension
	for _, c := range name {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.') {
			return "", fmt.Errorf("invalid character in filename: %c", c)
		}
	}
	return name, nil
}

// verifyHMAC checks the integrity signature
func verifyHMAC(message, signature string) bool {
	mac := hmac.New(sha256.New, hmacSecret)
	mac.Write([]byte(message))
	expected := hex.EncodeToString(mac.Sum(nil))
	return hmac.Equal([]byte(expected), []byte(signature))
}

// computeAssembledSize calculates the final buffer size needed
// This accounts for the 4-byte length prefix before each chunk
// Format: [len1][chunk1][len2][chunk2]...
func computeAssembledSize(upload *ChunkedUpload) (int64, error) {
	var totalNeeded int64
	for _, chunk := range upload.chunks {
		chunkLen := int64(len(chunk))
		// Each chunk needs 4 bytes for length prefix + actual data
		totalNeeded += 4 + chunkLen
		// Overflow check
		if totalNeeded < 0 || totalNeeded > int64(maxTotalSize)*2 {
			return 0, fmt.Errorf("assembled size overflow")
		}
	}
	return totalNeeded, nil
}

// assembleChunks creates the final binary format with length-prefixed chunks
func assembleChunks(upload *ChunkedUpload) ([]byte, error) {
	assembledSize, err := computeAssembledSize(upload)
	if err != nil {
		return nil, err
	}

	// Safety check: assembled size must be positive and within limits
	if assembledSize <= 0 || assembledSize > int64(maxTotalSize)*2 {
		return nil, fmt.Errorf("invalid assembled size: %d", assembledSize)
	}

	buf := make([]byte, assembledSize)
	offset := 0

	for _, chunk := range upload.chunks {
		// Write 4-byte big-endian length prefix
		binary.BigEndian.PutUint32(buf[offset:offset+4], uint32(len(chunk)))
		offset += 4
		// Copy chunk data
		copy(buf[offset:], chunk)
		offset += len(chunk)
	}

	return buf, nil
}

func initUploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	uploadID := r.Header.Get("X-Upload-ID")
	filename := r.Header.Get("X-Filename")
	expectedLenStr := r.Header.Get("X-Expected-Length")
	signature := r.Header.Get("X-Signature")

	if uploadID == "" || filename == "" || expectedLenStr == "" {
		http.Error(w, "Missing required headers", http.StatusBadRequest)
		return
	}

	// Verify request integrity
	msg := fmt.Sprintf("%s:%s:%s", uploadID, filename, expectedLenStr)
	if !verifyHMAC(msg, signature) {
		http.Error(w, "Invalid signature", http.StatusForbidden)
		return
	}

	safeName, err := sanitizeFilename(filename)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	var expectedLen int64
	if n, err := fmt.Sscanf(expectedLenStr, "%d", &expectedLen); n != 1 || err != nil {
		http.Error(w, "Invalid expected length", http.StatusBadRequest)
		return
	}
	if expectedLen <= 0 || expectedLen > int64(maxTotalSize) {
		http.Error(w, "Invalid expected length", http.StatusBadRequest)
		return
	}

	uploadsMu.Lock()
	uploads[uploadID] = &ChunkedUpload{
		filename:    safeName,
		chunks:      make([][]byte, 0),
		totalSize:   0,
		numChunks:   0,
		expectedLen: expectedLen,
	}
	uploadsMu.Unlock()

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "Upload initialized: %s", uploadID)
}

func chunkUploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	uploadID := r.Header.Get("X-Upload-ID")
	signature := r.Header.Get("X-Chunk-Signature")

	uploadsMu.RLock()
	upload, exists := uploads[uploadID]
	uploadsMu.RUnlock()

	if !exists {
		http.Error(w, "Upload not found", http.StatusNotFound)
		return
	}

	upload.mu.Lock()
	defer upload.mu.Unlock()

	if upload.finalized {
		http.Error(w, "Upload already finalized", http.StatusConflict)
		return
	}

	// Read chunk data with size limit
	data, err := io.ReadAll(io.LimitReader(r.Body, maxChunkSize))
	if err != nil {
		http.Error(w, "Failed to read chunk", http.StatusInternalServerError)
		return
	}

	// Verify chunk integrity
	chunkMsg := fmt.Sprintf("%s:%d:%d", uploadID, upload.numChunks, len(data))
	if !verifyHMAC(chunkMsg, signature) {
		http.Error(w, "Invalid chunk signature", http.StatusForbidden)
		return
	}

	// Check if adding this chunk would exceed expected length
	newTotal := upload.totalSize + int64(len(data))
	if newTotal < 0 || newTotal > upload.expectedLen {
		http.Error(w, "Upload exceeds declared size", http.StatusBadRequest)
		return
	}

	upload.chunks = append(upload.chunks, data)
	upload.totalSize = newTotal
	upload.numChunks++

	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "Chunk %d accepted, total: %d/%d", upload.numChunks, upload.totalSize, upload.expectedLen)
}

func finalizeUploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	uploadID := r.Header.Get("X-Upload-ID")
	signature := r.Header.Get("X-Finalize-Signature")

	// Verify finalization request
	finalMsg := fmt.Sprintf("finalize:%s", uploadID)
	if !verifyHMAC(finalMsg, signature) {
		http.Error(w, "Invalid signature", http.StatusForbidden)
		return
	}

	uploadsMu.RLock()
	upload, exists := uploads[uploadID]
	uploadsMu.RUnlock()

	if !exists {
		http.Error(w, "Upload not found", http.StatusNotFound)
		return
	}

	upload.mu.Lock()
	defer upload.mu.Unlock()

	if upload.finalized {
		http.Error(w, "Already finalized", http.StatusConflict)
		return
	}

	upload.finalized = true

	// Assemble chunks into final format
	assembled, err := assembleChunks(upload)
	if err != nil {
		http.Error(w, fmt.Sprintf("Assembly failed: %v", err), http.StatusInternalServerError)
		return
	}

	// Write to disk
	outPath := filepath.Join(uploadDir, upload.filename)
	err = os.WriteFile(outPath, assembled, 0644)
	if err != nil {
		http.Error(w, "Failed to write file", http.StatusInternalServerError)
		return
	}

	// Cleanup
	uploadsMu.Lock()
	delete(uploads, uploadID)
	uploadsMu.Unlock()

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Upload complete: %s (%d bytes)", upload.filename, len(assembled))
}

func main() {
	secret := os.Getenv("HMAC_SECRET")
	if secret == "" {
		fmt.Fprintln(os.Stderr, "HMAC_SECRET environment variable must be set")
		os.Exit(1)
	}
	hmacSecret = []byte(secret)

	mux := http.NewServeMux()
	mux.HandleFunc("/upload/init", initUploadHandler)
	mux.HandleFunc("/upload/chunk", chunkUploadHandler)
	mux.HandleFunc("/upload/finalize", finalizeUploadHandler)

	server := &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	fmt.Println("Chunked upload server starting on :8080")
	server.ListenAndServe()
}
